      +'<div class="pv-name"><strong>'+esc(b.name||b.provider)+"</strong><small>"+esc(b.label||(ok?"API · official":"不可查询"))+"</small>"
      +(pct!=null?'<div class="track"><i style="width:'+pct.toFixed(0)+'%"></i></div>':"")+"</div>"
      +"<b>"+val+"</b>"
