async function miniRing(pct,label,sub){const rem=Math.max(0,Math.min(100,pct));return '<div class="win-card card"><div class="wr"><svg viewBox="0 0 100 100"><circle class="wt" cx="50" cy="50" r="40"></circle><circle class="wp" cx="50" cy="50" r="40" pathLength="100" style="stroke-dasharray:'+rem.toFixed(1)+' '+(100-rem).toFixed(1)+'"></circle></svg><div class="wc"><b>'+rem.toFixed(0)+'%</b><span>'+esc(label)+'</span></div></div>'+(sub?'<code>'+esc(sub)+'</code>':'')+'</div>';}

const SPEND={mode:"line",unit:"day"};
function spendSyncHead(){const te=$("#spendTitle");if(te)te.textContent={day:"近 30 天费用",month:"按月费用",year:"按年费用"}[SPEND.unit];const se=$("#spendSub");if(se)se.textContent="按"+({day:"日",month:"月",year:"年"})[SPEND.unit]+"聚合 · 全局用量账本";syncSeg(document.getElementById("spendUnitSeg"),SPEND.unit);syncSeg(document.getElementById("spendModeSeg"),SPEND.mode);}
function spendData(){const days=state.ledger?.days||{};const keys=Object.keys(days).sort();
if(SPEND.unit==="day"){const out=[];for(let i=29;i>=0;i--){const d=new Date(Date.now()-i*864e5).toISOString().slice(0,10);out.push([d.slice(5),Number(days[d]?.cost)||0]);}return out;}
if(SPEND.unit==="month"){if(!keys.length)return[];const map={};keys.forEach(k=>{const m=k.slice(0,7);map[m]=(map[m]||0)+Number(days[k]?.cost||0);});let cur=keys[0].slice(0,7);const endCur=new Date().toISOString().slice(0,7);const out=[];let guard=0;while(cur<=endCur&&guard<240){out.push([cur,map[cur]||0]);const parts=cur.split("-").map(Number);cur=parts[1]===12?(parts[0]+1)+"-01":parts[0]+"-"+String(parts[1]+1).padStart(2,"0");guard++;}return out.slice(-24);}
const ymap={};keys.forEach(k=>{const y=k.slice(0,4);ymap[y]=(ymap[y]||0)+Number(days[k]?.cost||0);});return Object.keys(ymap).sort().map(y=>[y,ymap[y]]);}
function renderSpendPanel(){const box=$("#providerSpend");if(!box)return;if(!state.ledger){box.innerHTML='<div class="empty">账本不可用</div>';return;}const data=spendData();const max=Math.max(...data.map(x=>x[1]),1e-9);
if(SPEND.mode==="heat"){box.innerHTML='<div class="heat" style="grid-template-columns:repeat('+Math.min(Math.max(data.length,6),45)+',1fr)">'+data.map(d=>'<i class="l'+Math.round(Math.min(4,d[1]/max*4))+'" title="'+esc(d[0])+' · '+fmtCost(d[1])+'"></i>').join("")+"</div>";}
else{box.innerHTML=line(data.map(d=>d[1]),{format:fmtCost,stroke:"var(--accent)",xLabels:i=>data[i]?data[i][0]:"",xticks:Math.min(9,data.length)});}
spendSyncHead();}
function syncSeg(seg,val){if(!seg)return;const opts=[].slice.call(seg.querySelectorAll("[data-v]"));const idx=Math.max(0,opts.findIndex(o=>o.dataset.v===val));opts.forEach((o,i)=>o.classList.toggle("active",i===idx));const th=seg.querySelector(".seg-thumb");if(th){th.style.transform="translateX("+(idx*100)+"%)";}}
