function renderPricingTable(){const box=$("#pricingList");if(!box)return;const pr=state.pricing;if(!pr||!Array.isArray(pr.rows)||!pr.rows.length){box.innerHTML='<div class="empty">暂无价格数据</div>';return;}const tierLabel={peak:"高峰",offPeak:"闲时",flat:""};box.innerHTML=pr.rows.map(r=>{const srcNote=esc(r.note||"");return '<div class="price-row" title="'+srcNote+'"><div class="pr-model"><strong>'+esc(r.model)+'</strong><small>'+esc(r.provider||"–")+(tierLabel[r.tier]?" "+tierLabel[r.tier]:"")+'</small></div><div class="pr-cells"><span class="pr-cell"><em>未命中</em><b>'+fmtCost(r.miss)+'</b></span><span class="pr-cell"><em>命中</em><b>'+fmtCost(r.hit)+'</b></span><span class="pr-cell"><em>输出</em><b>'+fmtCost(r.out)+'</b></span></div><span class="badge '+(r.tier==="peak"?"":"warn")+'">'+srcNote+'</span></div>';}).join('');const meta=$("#pricingMeta");if(meta)meta.textContent="每百万 Token（元）· 配置快照 "+(pr.snapshotAt||"未知")+" · 非实时，随官方调整由配置更新";}
function setLoading(on){const btn=document.getElementById("refreshBtn"),ic=document.getElementById("btnIc"),tx=document.getElementById("btnTx");if(!btn)return;btn.disabled=on;if(on){btn.classList.add("loading");if(tx)tx.textContent="刷新中";}else{btn.classList.remove("loading");if(ic){ic.textContent="✓";ic.classList.add("done");}if(tx)tx.textContent="已刷新";setTimeout(()=>{if(ic&&!btn.classList.contains("loading")){ic.textContent="↻";ic.classList.remove("done");}if(tx&&!btn.classList.contains("loading"))tx.textContent="刷新";},1000);}}
function openExternal(url){const aFallback=()=>{try{const a=document.createElement("a");a.href=url;a.target="_blank";a.rel="noopener noreferrer";document.body.appendChild(a);a.click();a.remove();return true;}catch(e){return false;}};const hostFallback=()=>{try{const p=hana.external?.open?hana.external.open({url}):null;const t=setTimeout(aFallback,1000);if(p&&typeof p.then==="function"){p.then(()=>clearTimeout(t),()=>{clearTimeout(t);aFallback();});}}catch(e){aFallback();}};fetchJson("/api/open?url="+encodeURIComponent(url)).then(r=>{if(!r||r.ok!==true)hostFallback();}).catch(()=>hostFallback());}
