async function doUpdateCheck(){const btn=document.getElementById("updateCheckBtn"),ic=document.getElementById("updateCheckIc"),tx=document.getElementById("updateCheckTx");if(!btn)return;btn.disabled=true;btn.classList.add("loading");if(ic)ic.textContent="↻";if(tx)tx.textContent="检查中";try{const info=await fetchJson("/api/check-update");if(!info.updateAvailable){await showUpdateNotice("已是最新版本","当前版本 v"+(info.currentVersion||"未知"));return;}if(!info.hasInstallAsset)throw new Error("新版 Release 中没有找到 ZIP 安装包");await showUpdateNotice("检查到新版本 v"+info.latestVersion,"当前版本 v"+(info.currentVersion||"未知")+"，关闭提示后开始热更新。","开始更新");if(tx)tx.textContent="更新中";const response=await hana.api.fetch("/api/apply-update",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({version:info.latestVersion}),signal:AbortSignal.timeout(120000)});const result=await response.json().catch(()=>({}));if(!response.ok||!result.ok)throw new Error(result.error||("HTTP "+response.status));const next=new URL(window.location.href);next.searchParams.set("hot",Date.now().toString(36));window.location.replace(next.toString());}catch(error){await showUpdateNotice("检查更新失败",String(error?.message||error),"关闭");}finally{btn.disabled=false;btn.classList.remove("loading");if(ic)ic.textContent="⇧";if(tx)tx.textContent="检查更新";}}
