let focusedFile=null;let activeSessionFile=null;let focusedEntryId=null;let focusedFileFailUntil=0;async function getFocusedSessionFile(){if(Date.now()<focusedFileFailUntil)return focusedFile;try{const r=await fetch(hostApiUrl("/api/sessions/messages?limit=5"),{credentials:"include",signal:AbortSignal.timeout(5000)});if(!r.ok)throw new Error("focus "+r.status);const d=await r.json();const msg=(Array.isArray(d?.messages)?[...d.messages].reverse():[]).find(x=>typeof x?.entryId==="string"&&x.entryId.trim());const entryId=msg?.entryId?.trim()||null;if(entryId&&entryId===focusedEntryId&&focusedFile)return focusedFile;if(entryId){const mapped=await fetchJson("/api/resolve-entry?entryId="+encodeURIComponent(entryId));if(typeof mapped?.file==="string"&&mapped.file.endsWith(".jsonl")){focusedEntryId=entryId;focusedFile=mapped.file;focusedFileFailUntil=0;return focusedFile;}}}catch{}try{const active=await fetchJson("/api/active");if(typeof active?.file==="string"&&active.file.endsWith(".jsonl")){focusedFile=active.file;focusedFileFailUntil=0;return focusedFile;}}catch{}focusedFileFailUntil=Date.now()+5000;return focusedFile;}
let widgetRefreshSeq=0;async function loadWidget(){const thisRefresh=++widgetRefreshSeq;const requestedFile=activeSessionFile;const statsPath=requestedFile?"/api/stats?file="+encodeURIComponent(requestedFile):"/api/stats";const [stats,balance]=await Promise.all([fetchJson(statsPath).catch(()=>null),fetchJson("/api/balance").catch(()=>null)]);if(thisRefresh!==widgetRefreshSeq||requestedFile!==activeSessionFile)return;state.stats=stats;state.balance=balance;renderWidget();}
async function loadPage(force){const q=force?"?force=1":"";const jobs=[fetchJson("/api/stats").then(r=>state.stats=r).catch(()=>state.stats=null),fetchJson("/api/ledger-stats"+q).then(r=>state.ledger=r).catch(()=>state.ledger=null),fetchJson("/api/balance"+q).then(r=>state.balance=r).catch(()=>state.balance=null),fetchJson("/api/sessions").then(r=>state.sessions=r).catch(()=>state.sessions=null),fetchJson("/api/total-cost").then(r=>state.totalCost=r).catch(()=>state.totalCost=null),fetchJson("/api/rules").then(r=>state.rules=r).catch(()=>state.rules={}),fetchJson("/api/pricing").then(r=>state.pricing=r).catch(()=>state.pricing=null)];await Promise.all(jobs);renderPageAll();}
async function saveRules(provider,payload){try{const r=await pluginApiFetch("/rules",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.assign({provider},payload))});const j=await r.json().catch(()=>null);if(j&&j.ok&&state.rules){state.rules=Object.assign({},state.rules,{[provider]:j.saved});}return j;}catch(e){return null;}}

