function renderChartDetail(card){const type=card.dataset.chart||'',st=state.stats||{},ser=st.series||[],lg=state.ledger||{};if(type==='context'){const vals=ser.map(s=>s.cumTokens||0);return `<div class="card w-detail-visual si-rise">${line(vals,{w:840,h:280,format:fmtTokens,xLabels:i=>'#'+(i+1),xticks:8})}</div>`;}if(type==='cost'){return `<div class="card w-detail-visual si-rise">${bars(ser.map(s=>s.cost||0),{w:840,h:280,format:fmtCost,xLabels:i=>'#'+(i+1),xticks:8})}</div>`;}if(type==='turnStack'){return `<div class="card w-detail-visual si-rise">${stack(ser.map(s=>({a:s.cacheRead||0,b:s.input||0,c:(s.output||0)+(s.reasoning||0)})),{w:840,h:280,xLabels:i=>'#'+(i+1),xticks:8})}</div>`;}if(type==='cache'){return `<div class="card w-detail-visual si-rise">${line(ser.map(s=>s.hit||0),{w:840,h:280,format:fmtPct,yMax:100,xLabels:i=>'#'+(i+1),xticks:8})}</div>`;}if(type==='latency'){const b=lg.latency?.buckets||{};return `<div class="card w-detail-visual si-rise">${bars([b.lt1||0,b['1_3']||0,b['3_10']||0,b.gt10||0],{w:840,h:280,format:v=>String(Math.round(v)),xLabels:['<1s','1–3s','3–10s','>10s'],xticks:4})}</div>`;}return '<div class="empty">该卡片暂无放大视图</div>';}
