const detailReleaseTimers=new WeakMap();
function clearDetailRelease(c){const t=detailReleaseTimers.get(c);if(t)clearTimeout(t);detailReleaseTimers.delete(c);c.classList.remove('si-dynamic-release');c.style.transform='';c.style.transition='';}
function detailReleaseTo(c,inside){const old=detailReleaseTimers.get(c);if(old)clearTimeout(old);c.classList.remove('si-press','si-release');c.classList.add('si-dynamic-release');c.style.transition='transform .46s cubic-bezier(.16,.82,.24,1),border-color .2s,box-shadow .2s';requestAnimationFrame(()=>{c.style.transform=inside?'scale(1.025)':'scale(1)';});const t=setTimeout(()=>{c.classList.remove('si-dynamic-release');c.style.transform='';c.style.transition='';detailReleaseTimers.delete(c);},480);detailReleaseTimers.set(c,t);}

function initPageEvents(){document.addEventListener('click',e=>{if(surface==='widget'){if(e.target.closest('[data-detail-close]')||e.target.id==='wDetail'){closeWidgetDetail();return;}const d=e.target.closest('.widget [data-detail]');if(d){openWidgetDetail(d.dataset.detail,d.dataset.provider);return;}return;}if(e.target.closest('[data-detail-close]')||e.target.id==='wDetail'){closeWidgetDetail();return;}const back=e.target.closest('#apiBack');if(back){nav('api','api-overview');return;}const opt=e.target.closest('.seg [data-v]');if(opt){const seg=opt.closest('.seg'),v=opt.dataset.v;if(seg.id==='spendUnitSeg'){SPEND.unit=v;renderSpendPanel();}else if(seg.id==='spendModeSeg'){SPEND.mode=v;renderSpendPanel();}else if(seg.id==='costUnitSeg'){COST.unit=v;renderCostPanel();}else if(seg.id==='costModeSeg'){COST.mode=v;renderCostPanel();}flashSeg(seg);return;}const q=e.target.closest('[data-open]');if(q){openExternal(q.dataset.open);return;}const tab=e.target.closest('.tab');if(tab){nav(tab.dataset.view,tab.dataset.view==='usage'?'usage-overview':'api-overview');return;}const sub=e.target.closest('.subtab');if(sub){const sc=sub.closest('.subnav')?.dataset.scope||sub.closest('.view')?.id.replace('view-','')||'usage';setPage(sub.dataset.page,sc);return;}const p=e.target.closest('.provider-item');if(p){showProvider(p.dataset.provider);nav('api','api-detail');return;}const row=e.target.closest('.session-row');if(row){nav('usage','usage-session');return;}const chart=e.target.closest('.chart-card[data-chart]:not(.no-modal)');if(chart){openModal(chart);return;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeWidgetDetail();});document.addEventListener('change',e=>{if(!['thEnabled','thPct','thFail'].includes(e.target.id))return;saveRules(state.provider,{enabled:$('#thEnabled')?.checked||false,pct:Number($('#thPct')?.value)||20,fail:Number($('#thFail')?.value)||3});});
document.addEventListener('mousedown',e=>{const c=e.target.closest('.card,.panel,.provider-item,.chart-card');if(c){if(c.closest('.w-detail-card'))clearDetailRelease(c);c.classList.remove('si-release');c.classList.add('si-press');}},true);document.addEventListener('mouseup',()=>{$$('.si-press').forEach(c=>{if(c.closest('.w-detail-card'))detailReleaseTo(c,c.matches(':hover'));else{c.classList.remove('si-press');c.classList.add('si-release');setTimeout(()=>c.classList.remove('si-release'),650);}});},true);document.addEventListener('mouseout',e=>{const c=e.target.closest?.('.w-detail-card .card.si-dynamic-release');if(c&&!c.contains(e.relatedTarget))detailReleaseTo(c,false);},true);document.addEventListener('mouseover',e=>{const c=e.target.closest?.('.w-detail-card .card.si-dynamic-release');if(c&&!c.contains(e.relatedTarget))detailReleaseTo(c,true);},true);}

let glowRaf=null,glowMx=0,glowMy=0,glowCard=null,glowCache=[],glowPrev=null;
function updateGlow(){glowRaf=null;const card=document.elementFromPoint(glowMx,glowMy)?.closest('.card,.panel,.provider-item,.chart-card');if(!card){if(glowPrev){glowPrev.spot?.style.setProperty('opacity','0');glowPrev.bord?.style.setProperty('opacity','0');glowPrev=null;}glowCache.forEach(x=>x.el.style.setProperty('--glow-t','0'));glowCard=null;glowCache=[];return;}const r=card.getBoundingClientRect();if(!card.querySelector('.si-glow-spot')){const x=document.createElement('div');x.className='si-glow-spot';card.prepend(x);}if(!card.querySelector('.si-border-glow')){const x=document.createElement('div');x.className='si-border-glow';card.prepend(x);}const spot=card.querySelector('.si-glow-spot'),bord=card.querySelector('.si-border-glow');if(glowPrev&&glowPrev.spot!==spot){glowPrev.spot.style.opacity='0';glowPrev.bord.style.opacity='0';}glowPrev={spot,bord};spot.style.opacity='1';bord.style.opacity='1';if(card!==glowCard){glowCache.forEach(x=>x.el.style.setProperty('--glow-t','0'));glowCard=card;glowCache=Array.from(card.querySelectorAll('.glow-text,h3,.card span,.card b,.metric span,.metric b,.metric em')).filter(el=>el.closest('.card,.chart-card,.provider-item')===card).map(el=>{const er=el.getBoundingClientRect();return{el,rx:er.left+er.width/2-r.left,ry:er.top+er.height/2-r.top};});}card.style.setProperty('--mx',((glowMx-r.left)/r.width*100).toFixed(1)+'%');card.style.setProperty('--my',((glowMy-r.top)/r.height*100).toFixed(1)+'%');card.style.setProperty('--ang',((Math.atan2(glowMy-(r.top+r.height/2),glowMx-(r.left+r.width/2))*180)/Math.PI+90).toFixed(1)+'deg');const md=Math.min(170,r.width,r.height);glowCache.forEach(x=>{const dx=x.rx-(glowMx-r.left),dy=x.ry-(glowMy-r.top),g=md>0?Math.max(0,1-Math.sqrt(dx*dx+dy*dy)/md):0;x.el.style.setProperty('--glow-t',g.toFixed(2));});}

